auto result = octree.GetNearestNeighbors(searchPoint, k);

// Extract indices from the result
std::vector<size_t> indices;
indices.reserve(result.size());
for (const auto& neighbor : result) {
    indices.push_back(neighbor.EntityID);
}

return indices;

